# Event-driven system with a simple event bus
class EventBus:
    def __init__(self):
        self._subscribers = {}

    def subscribe(self, event_type, handler):
        self._subscribers.setdefault(event_type, []).append(handler)

    def publish(self, event_type, payload):
        print(f'[Bus] event published: {event_type} -> {payload}')
        for handler in self._subscribers.get(event_type, []):
            handler(payload)

bus = EventBus()

def on_order_placed(payload):
    print(f'[InventoryService] reserving stock for order {payload["order_id"]}')

def on_order_placed_notify(payload):
    print(f'[EmailService] sending confirmation to {payload["email"]}')

bus.subscribe('OrderPlaced', on_order_placed)
bus.subscribe('OrderPlaced', on_order_placed_notify)

bus.publish('OrderPlaced', {'order_id': 101, 'email': 'alice@example.com', 'item': 'Widget'})

